begin;
update public.lessons set ord=2 where id='2-1';
update public.lessons set ord=3 where id='2-2';
update public.lessons set ord=4 where id='2-3';
update public.lessons set ord=5 where id='2-4';
insert into public.lessons (id,level,ord,title,hook,mins,is_free,body,scenes,quiz,audio_url) values ('2-5',2,1,'كيف تمسك وحدة التحكم صح','نص دقتك في الطيران تبدأ من طريقة مسكتك.',5,false,'[["p","طريقة مسكك لوحدة التحكم تحدد نعومة حركاتك ودقتها. فيه مسكتان أساسيتان، وما فيه وحدة صح ووحدة غلط. المهم تختار وحدة وتتعوّد عليها."],["ul",["<b>مسكة الإبهام</b> <span class=\"en\">Thumbs</span>: طرف الإبهام فوق العصا، وباقي الأصابع تسند الجهاز من تحت. الأسهل للبداية، ومناسبة لطائرات التصوير.","<b>مسكة القرصة</b> <span class=\"en\">Pinch</span>: العصا بين الإبهام والسبابة. دقة أعلى وحركات أنعم، ويستخدمها طيارو FPV والسباقات."]],["p","<b>عشان تكون مسكتك صحيحة:</b>"],["ul",["تحكّم بطرف الإبهام، مو بالمفصل كامل.","ارخِ يدك، الشد يخلي الحركة قوية ومفاجئة.","ثبّت الجهاز على مستوى الصدر، والأفضل بحبل رقبة، واسند كوعيك على جسمك.","حركات صغيرة: ربع مسافة العصا يكفي في أغلب الطيران.","لا تترك العصا فجأة، ارجع للمنتصف بهدوء."]],["tip","الهوائي: أقوى إشارة تطلع من جنب الهوائي. خلّ جنب الهوائيات مقابل الطائرة، ولا تأشر براسها عليها."],["warn","لا تشيل يدك عن العصي والطائرة في الجو، حتى لو كانت تحوم بثبات."],["tip","في المحاكي: جرّب كل مسكة ١٠ دقائق في مهمة التحويم، واختار اللي ترتاح لها. ومن «حساسية التحكم» تقدر تخفف السرعة لين تتعوّد."]]'::jsonb,'[{"v":"grip-thumbs","cap":"مسكة الإبهام: الأسهل للبداية","say":"أشهر مسكة هي مسكة الإبهام: تحط طرف إبهامك فوق راس العصا، وباقي أصابعك تحت الجهاز تسنده. مريحة وسهلة للمبتدئ."},{"v":"grip-pinch","cap":"مسكة القرصة: دقة أعلى","say":"والمسكة الثانية اسمها القرصة: تمسك العصا بين الإبهام والسبابة. حركتك تصير أنعم وأدق، ويستخدمها طيارين الأكرو والسباقات."},{"v":"grip-tip","cap":"بطرف الإبهام، مو بالمفصل","say":"وخل التحكم بطرف الإبهام، مو بالمفصل كامل. وارخِ يدك، المسكة المشدودة تخلي حركاتك قوية ومفاجئة."},{"v":"grip-posture","cap":"ثبّت الجهاز واسند كوعك","say":"ثبّت الجهاز قدامك على مستوى الصدر، والأفضل تعلقه بحبل الرقبة وتسند كوعينك على جسمك. كذا يدينك ما تتعب ولا ترجف."},{"v":"grip-antenna","cap":"جنب الهوائي باتجاه الطائرة","say":"وانتبه للهوائيات: أقوى إشارة تطلع من جنب الهوائي، مو من راسه. خل جنبها مقابل الطيارة، ولا تأشر براسها عليها."},{"v":"points","cap":"تمرين بسيط","pts":["ربع مسافة العصا يكفي غالباً","ارجع للمنتصف بهدوء","١٠ دقائق تحويم في المحاكي لكل مسكة"],"say":"وتمرين بسيط: حرك العصا ربع المسافة بس، وارجع للمنتصف بهدوء. وجرب عشر دقايق تحويم في المحاكي بكل مسكة، واختار اللي ترتاح لها."}]'::jsonb,'[{"q":"في مسكة القرصة Pinch، كيف تمسك العصا؟","o":["بطرف الإبهام من فوق","بين الإبهام والسبابة","بكف اليد كاملة"],"a":1,"w":"القرصة تعطي دقة أعلى وحركات أنعم."},{"q":"من أي جزء تطلع أقوى إشارة من الهوائي؟","o":["من رأسه","من جنبه","من قاعدته"],"a":1,"w":"خلّ جنب الهوائي مقابل الطائرة."},{"q":"وش الأفضل لثبات يدك وقلة التعب؟","o":["شد اليد بقوة","إسناد الكوعين وحبل الرقبة","رفع الجهاز فوق مستوى العين"],"a":1,"w":"الإسناد يقلل الرجفة والتعب."}]'::jsonb,null) on conflict (id) do update set level=excluded.level, ord=excluded.ord, title=excluded.title, hook=excluded.hook, mins=excluded.mins, body=excluded.body, scenes=excluded.scenes, quiz=excluded.quiz;
commit;
select id,ord,title from public.lessons where level=2 order by ord;
